package com.CosRoom;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CosRoomPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CosRoomPlugin.class);
		RuneLite.main(args);
	}
}

package com.CosRoom;

import com.CosRoom.items.*;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;

public class CostumeHighlightOverlay extends WidgetItemOverlay {
    private final ItemManager itemMan;
    private final CosRoomConfig config;
    private final ToyBox toyBox;
    private final ArmorCase armorCase;
    private final CapeRack capeRack;
    private final FancyDressBox fancyDressBox;
    private final MagicWardrobe magicWardrobe;
    private final TreasureChest treasureChest;

    @Inject
    private CostumeHighlightOverlay(ItemManager itemMan, CosRoomPlugin plugin, CosRoomConfig config)
    {
        this.config = config;
        this.itemMan = itemMan;
        this.toyBox = new ToyBox();
        this.armorCase = new ArmorCase();
        this.capeRack = new CapeRack();
        this.fancyDressBox = new FancyDressBox();
        this.magicWardrobe = new MagicWardrobe();
        this.treasureChest = new TreasureChest();
        showOnBank();
        if(config.outsideBankEnabled()) {
            showOnInterfaces(InterfaceID.SHOP, InterfaceID.SHOP_INVENTORY);
            showOnInventory();
        }
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemID, WidgetItem itemWidget)
    {
        Color highlightColor = config.getHouseColor();
        if(checkStorability(itemID))
        {
            Rectangle bounds = itemWidget.getCanvasBounds();
            final BufferedImage outline = itemMan.getItemOutline(itemID, itemWidget.getQuantity(), highlightColor);
            graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
        }
    }

    private boolean checkStorability(int itemID)
    {
        if(config.toyBoxEnabled() && toyBox.checkList(itemID)) return true;
        if(config.armorCaseEnabled() && armorCase.checkList(itemID)) return true;
        if(config.CapeRackEnabled() && capeRack.checkList(itemID)) return true;
        if(config.FancyDressBoxEnabled() && fancyDressBox.checkList(itemID)) return true;
        if(config.MagicWardrobeEnabled() && magicWardrobe.checkList(itemID)) return true;
        if(config.TreasureChestEnabled() && treasureChest.checkList(itemID)) return true;
        return false;
    }
}

package com.CosRoom;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import java.awt.Color;

@ConfigGroup("costumeroomchecker")
public interface CosRoomConfig extends Config
{
	@ConfigItem(
		keyName = "storeableColor",
		name = "Storable Color",
		description = "The color to highlight items that can be stored in a house"
	)
	default Color getHouseColor()
	{
		return Color.PINK;
	}

	@ConfigItem(
			keyName = "OutsideBank",
			name = "Show Outside Bank",
			description = "Choose if you wish to highlight items when not in your bank tab. This includes your inventory and certain shops."
	)
	default boolean outsideBankEnabled() { return false; }

	@ConfigItem(
			keyName = "toyBoxEnable",
			name = "Enable Toy Box",
			description = "Choose if you wish to highlight the items that can be inserted into a toy box."
	)
	default boolean toyBoxEnabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "ArmorCase",
			name = "Enable Armor Case",
			description = "Choose if you wish to highlight the items that can be inserted into an armor case."
	)
	default boolean armorCaseEnabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "CapeRack",
			name = "Enable Cape Rack",
			description = "Choose if you wish to highlight the items that can be inserted into a cape rack."
	)
	default boolean CapeRackEnabled() { return true; }

	@ConfigItem(
			keyName = "FancyDressBox",
			name = "Enable Fancy Dress Box",
			description = "Choose if you wish to highlight the items that can be inserted into a fancy dress box."
	)
	default boolean FancyDressBoxEnabled() { return true; }

	@ConfigItem(
			keyName = "MagicWardrobe",
			name = "Enable Magic Wardrobe",
			description = "Choose if you wish to highlight the items that can be inserted into a magic wardrobe."
	)
	default boolean MagicWardrobeEnabled() { return true; }

	@ConfigItem(
			keyName = "TreasureChest",
			name = "Enable Treasure Chest",
			description = "APPLIES ON RESTART. Choose if you wish to highlight the items that can be inserted into a treasure chest."
	)
	default boolean TreasureChestEnabled() { return true; }
}

